  (4294967296 + 112 <= su)%Z -> (su <= 0x800000000000)%Z ->
  (0x11fc30 <= f)%Z -> (f + 232 <= 0x11fe10)%Z ->
  (su - 104 <= io)%Z -> (io + 16 <= su - 72)%Z ->
  (1 <= ic <= 2)%Z ->
